/// What one recorded call of RocketFigure.paintComponent() drew.
enum class PaintPinKind
{
    /// g2.draw() of a component's shape.
    SHAPE,
    /// drawMotors(): g2.fill() of a motor, then MOTOR_OUTLINE, its g2.draw().
    MOTOR_FILL,
    MOTOR_OUTLINE,
    /// Caret.paint(): g2.fill() of a caret's area (blue CG, red CP).
    CARET,
};

/// One recorded call, in the order of the paint: the colour, the stroke in device pixels (its
/// width and dashes times the scale; Java's SOLID is the dashes 10, 0, and a fill has no dashes)
/// and the bounds of the shape in device pixels (getBounds2D() of the transformed shape).
struct PaintPin
{
    PaintPinKind kind;
    /// The component's index in the rocket's tree (pre-order, the rocket 0), -1 for the others.
    int component;
    /// The component's display order in the view.
    int                   displayOrder;
    int                   red;
    int                   green;
    int                   blue;
    int                   alpha;
    double                width;
    std::array<double, 4> dashes;
    int                   dashCount;
    double                x;
    double                y;
    double                w;
    double                h;
    /// False for what QtRocket does not draw: a shape of a colour of alpha 0 (an invisible hit
    /// test shape, a component coloured so), a shape without extent (an empty path, Java's bounds
    /// (0, 0, 0, 0), or one whose points are all equal: the tip of a nose cone in the back view)
    /// and a caret at NaN (Java fills an empty area).
    bool drawn;
};

/// A caret's centre in device pixels and, for each of ten offsets from it, whether Java's area
/// holds the point there ('1' or '0'): (3, 3), (-3, -3), (3, -3), (-3, 3), (6.6, 0), (0, 6.6),
/// (7.5, 0), (5.8, 0), (0, 0.5) and (4.5, 0).
struct CaretPin
{
    double           centreX;
    double           centreY;
    std::string_view samples;
};

/// getComponentsByPoint() at a pixel of the figure: the tree indices of the components, in
/// QtRocket's order (Java's, each run of equal display order sorted by tree index). Only points
/// that give the same components a hundredth of a pixel away in every diagonal direction.
struct HitPin
{
    int              x;
    int              y;
    std::string_view components;
};

/// One figure: the design, how it was shown and what Java painted. The figure is that of
/// RocketPanel.create2DPreviewFigure() at 96 dots per inch: scaleTo(1000 x 700), updateFigure(),
/// its preferred size; the carets where RocketPanel.updateExtras() puts them.
struct PaintScenarioPin
{
    std::string_view name;
    /// "example" (a file of data/examples), "testrocket" (a TestRockets maker) or "new"
    /// (OpenRocketDocumentFactory.createNewRocket()).
    std::string_view source;
    std::string_view design;
    FigureView       view;
    double           rotation;
    /// The tree indices of the selected components, space separated.
    std::string_view selection;
    /// The preference ShowMarkers.
    bool showMarkers;
    /// "styled": the body tube (tree index 3) coloured (10, 20, 30, 255) and dotted, the parachute
    /// (4) dash-dotted, the nose cone (2) coloured (200, 100, 50, 0); "hide3": the body tube
    /// hidden; "": nothing.
    std::string_view          modification;
    double                    userScale;
    double                    absoluteScale;
    int                       originX;
    int                       originY;
    int                       width;
    int                       height;
    double                    cgX;
    double                    cgY;
    double                    cpX;
    double                    cpY;
    std::span<const PaintPin> paints;
    std::span<const CaretPin> carets;
    std::span<const HitPin>   hits;
};

/// What GoogleTest prints for the scenario of a test that failed: its name.
// NOLINTNEXTLINE(readability-identifier-naming): the name GoogleTest looks for
inline void PrintTo(const PaintScenarioPin& pin, std::ostream* out)
{
    *out << pin.name;
}

